import{_ as o,l,o as e,c as s,v as t,p as n,x as i,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"SIEM","description":"","frontmatter":{"title":"SIEM","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/siem-logging.md","filePath":"cs/siem-logging.md","lastUpdated":1789023840000}'),c={name:"cs/siem-logging.md"};function m(_,a,E,u,f,S){const r=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="siem" tabindex="-1">SIEM <a class="header-anchor" href="#siem" aria-label="Permalink to &quot;SIEM&quot;">​</a></h1><div class="epigraph"><p>安全信息和事件管理把日志汇聚、规范化、关联。没有可靠时间与身份字段，关联是噪音。日志完整性本身要防篡改，否则根kit 课的撒谎会延伸到记录。</p><footer>—— 据 NIST SP 800-92；对照可观测性课的三支柱只作点名</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/default-config-hardening">默认加固</a>要能证明改过。缺口是<strong>把证据送走并关联</strong>。本课讲日志合同：时钟、身份、外送、保留。不写如何擦日志的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主机本地日志可被改。外送到只增存储。缺口是字段：谁、何时、何客体、成功失败。关联规则误报与 IDS 同类。</p><h3 id="隐私" tabindex="-1">隐私 <a class="header-anchor" href="#隐私" aria-label="Permalink to &quot;隐私&quot;">​</a></h3><p>日志含个人数据，后课 GDPR 会回来。最小化字段。</p><p><span class="marginnote">SP 800-92。禁止日志伪造/擦除教程。事件响应下一课用这些证据。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列必须事件：认证、授权失败、管理、出站。下一课事件响应生命周期。</p>',12)),(e(),n(p,null,{default:i(()=>[h(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E4%B8%BB%E6%9C%BA%E4%B8%8E%E7%BD%91%E7%BB%9C%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20SHIP%5B%22%E5%A4%96%E9%80%81%22%5D%0A%20%20SHIP%20--%3E%20NORM%5B%22%E8%A7%84%E8%8C%83%E5%8C%96%22%5D%0A%20%20NORM%20--%3E%20CORR%5B%22%E5%85%B3%E8%81%94%E5%91%8A%E8%AD%A6%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>观测是响应的输入。时间不同步则因果链断。IR 下一课是流程。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写清日志。事件响应下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>加固要证据；SIEM 收证据。</li><li>外送与只增防篡改。</li><li>字段与时钟决定关联能否成立。</li><li>下一课事件响应。</li><li>出处：NIST SP 800-92。</li></ul>',8))])}const P=o(c,[["render",m]]);export{B as __pageData,P as default};
